var authRoutes = async (fastify2) => {
  fastify2.post("/api/v1/auth/login", async (request, reply) => {
    const { email, password } = request.body;
    if (!email || !password) {
      return reply.code(400).send({ error: "Email and password are required" });
    }
    const user = await store.findUserByEmail(email);
    if (!user) {
      return reply.code(401).send({ error: "Invalid email or password" });
    }
    const isValid = import_bcryptjs2.default.compareSync(password, user.passwordHash);
    if (!isValid) {
      return reply.code(401).send({ error: "Invalid email or password" });
    }
    const token = fastify2.jwt.sign(
      { id: user.id, email: user.email, role: user.role, name: user.name },
      { expiresIn: "7d" }
    );
    return reply.send({
      token,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role
      }
    });
  });
  fastify2.get("/api/v1/auth/me", {
    onRequest: [fastify2.authenticate]
  }, async (request) => {
    return { user: request.user };
  });
};

