      const minutesAgo = Math.max(1, Math.round((Date.now() - new Date(o.createdAt).getTime()) / 6e4));
      const timeStr = minutesAgo < 60 ? `${minutesAgo} min ago` : `${Math.round(minutesAgo / 60)} hours ago`;
